+   assert(Number.isInteger(y)&&y>=0&&y<size&&Number.isInteger(length)&&length>0&&length<=size);
+   result[owner].cells+=length;result[owner].grid_wgs84_area_m2+=length*nativeRowArea(y,size);result[owner].runs++;
